fn bounds(e: &BodyEntry2d) -> (Vec2, Vec2) {
    let half = match &e.collider.shape {
        ColliderShape2d::Box { half_extents } => Vec2::from(*half_extents),
        ColliderShape2d::Circle { radius } => Vec2::splat(*radius),
        ColliderShape2d::Capsule {
            half_height,
            radius,
        } => Vec2::new(*radius, *half_height + *radius),
        ColliderShape2d::Polygon { points } => points
            .iter()
            .fold(Vec2::ZERO, |max, point| max.max(Vec2::from(*point).abs())),
    };
    let half = half * e.pose.scale.abs();
    (e.pose.translation - half, e.pose.translation + half)
}
